// Map all read rows to a clean array of leads
const items = $input.all();

function extractLead(row, index) {
  const clean = (val) => (val !== undefined && val !== null ? String(val).trim() : "");
  const norm = (s) => String(s || "").toLowerCase().replace(/[^a-zа-яіїєґ0-9]/gi, "");
  const keys = Object.keys(row || {});

  const findByKey = (...patterns) => {
    // 1. Direct key match
    for (const p of patterns) {
      if (row[p] !== undefined && clean(row[p]) !== "") return clean(row[p]);
    }
    // 2. Normalized key match
    for (const p of patterns) {
      const target = norm(p);
      if (!target) continue;
      for (const k of keys) {
        if (k === "row_number") continue;
        const normK = norm(k);
        if (normK === target || (target.length >= 3 && (normK.includes(target) || target.includes(normK)))) {
          if (clean(row[k]) !== "") return clean(row[k]);
        }
      }
    }
    return "";
  };

  // Positional fallback (excluding metadata row_number)
  const nonMetaKeys = keys.filter(k => k !== "row_number" && !k.startsWith("_"));
  const getByColIndex = (idx) => {
    if (idx < nonMetaKeys.length) {
      return clean(row[nonMetaKeys[idx]]);
    }
    return "";
  };

  const timestamp = findByKey("Дата/Час", "Дата / Час", "Дата", "Час", "timestamp", "date", "time") || getByColIndex(0);
  const userId = findByKey("User ID", "userId", "user_id", "id", "юзер") || getByColIndex(1);
  const username = findByKey("Username", "username", "user_name", "нік", "юзернейм") || getByColIndex(2);
  const name = findByKey("Ім'я", "Ім’я", "Имя", "Імя", "name", "clientName", "client_name", "клієнт") || getByColIndex(3);
  const phone = findByKey("Телефон", "phone", "tel", "номер", "тел") || getByColIndex(4);
  const repairType = findByKey("Тип ремонту", "ремонт", "repairType", "repair_type", "scope") || getByColIndex(5);
  const propertyType = findByKey("Тип житла", "житло", "район", "локація", "district", "propertyType") || getByColIndex(6);
  const areaM2 = findByKey("Площа (м²)", "Площа (м2)", "Площа", "area", "areaM2", "area_m2") || getByColIndex(7);
  const addons = findByKey("Додаткові опції", "додаткові", "опції", "addons", "допи") || getByColIndex(8);
  const total = findByKey("Розрахунок (грн)", "Розрахунок", "кошторис", "сума", "total", "price", "cost") || getByColIndex(9);
  const rawStatus = findByKey("Статус", "status") || getByColIndex(10);
  const status = rawStatus || "Новий лід";

  return {
    id: index + 1,
    timestamp,
    userId,
    username,
    name,
    phone,
    repairType,
    propertyType,
    areaM2,
    addons,
    total,
    status
  };
}

const leads = items.map((item, index) => extractLead(item.json, index)).reverse();

return [{
  json: {
    success: true,
    count: leads.length,
    leads: leads
  }
}];

